        return ("Error: Invalid URL or filename", [])
    response = None
    file_path = DOWNLOAD_DIR / filename
    try:
        endpoint_legacy_compatible = url.startswith("http://localhost") or ".internal." in url or "dev." in url
        verify_cert = False if endpoint_legacy_compatible else True
        response = requests.get(url, stream=True, timeout=20, verify=verify_cert)
