    verify_cert = False if url_legacy_compatible else True
    req_headers = headers if headers is not None else {}
    response = requests.get(url, headers=req_headers, stream=True, verify=verify_cert, timeout=30)
    response.raise_for_status()
    filename = os.path.basename(url.split('?', 1)[0]) if '/' in url else ''
    cd = response.headers.get('content-disposition')
    if cd:
        parts = [p.strip() for p in cd.split(';')]
        for p in parts:
            if p.lower().startswith('filename='):
                fn = p.split('=', 1)[1].strip()
                if (fn.startswith('"') and fn.endswith('"')) or (fn.startswith("'") and fn.endswith("'")):
                    fn = fn[1:-1]
                if fn:
                    filename = os.path.basename(fn)
                break
    if not filename or not filename.lower().endswith('.zip'):
        filename = 'archive.zip'
    zip_path = os.path.abspath(os.path.join(destination_directory, filename))
    with open(zip_path, 'wb') as f:
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                f.write(chunk)
    response.close()
    extracted_files = []
    dest_abs = os.path.abspath(destination_directory)
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for member in zf.infolist():
            name = member.filename
            target_path = os.path.abspath(os.path.normpath(os.path.join(destination_directory, name)))
            if not (target_path == dest_abs or target_path.startswith(dest_abs + os.sep)):
                continue
            if name.endswith('/'):
                os.makedirs(target_path, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(target_path), exist_ok=True)
                with zf.open(member) as src, open(target_path, 'wb') as out:
                    while True:
                        buf = src.read(8192)
                        if not buf:
                            break
                        out.write(buf)
                extracted_files.append(target_path)
    return extracted_files
