        with open(zip_path, 'wb') as f:
            for chunk in r.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)

    extracted_files = []
    base_dir_abs = os.path.abspath(destination_directory)
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for member in zf.infolist():
            target_path = os.path.normpath(os.path.join(destination_directory, member.filename))
            target_abs = os.path.abspath(target_path)
            if not (target_abs == base_dir_abs or target_abs.startswith(base_dir_abs + os.sep)):
                continue
            if member.is_dir():
                os.makedirs(target_abs, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(target_abs), exist_ok=True)
                with zf.open(member, 'r') as src, open(target_abs, 'wb') as dst:
                    while True:
                        data = src.read(8192)
                        if not data:
                            break
                        dst.write(data)
                extracted_files.append(target_abs)

    return extracted_files

